#include <stdio.h>
#include <stdlib.h>

#define MAX_N 200000

// Disjoint Set Union (Union-Find)
typedef struct {
    int parent[MAX_N + 1];
    int rank[MAX_N + 1];
} DSU;

void dsu_init(DSU *dsu, int n) {
    for (int i = 1; i <= n; i++) {
        dsu->parent[i] = i;
        dsu->rank[i] = 0;
    }
}

int dsu_find(DSU *dsu, int x) {
    if (dsu->parent[x] != x) {
        dsu->parent[x] = dsu_find(dsu, dsu->parent[x]);
    }
    return dsu->parent[x];
}

void dsu_union(DSU *dsu, int x, int y) {
    int rx = dsu_find(dsu, x);
    int ry = dsu_find(dsu, y);
    if (rx == ry) return;
    if (dsu->rank[rx] < dsu->rank[ry]) {
        dsu->parent[rx] = ry;
    } else if (dsu->rank[rx] > dsu->rank[ry]) {
        dsu->parent[ry] = rx;
    } else {
        dsu->parent[ry] = rx;
        dsu->rank[rx]++;
    }
}

// For coordinate compression: map (road_comp, rail_comp) -> group id
typedef struct {
    int road_comp;
    int rail_comp;
} Pair;

int pair_cmp(const void *a, const void *b) {
    Pair *pa = (Pair*)a;
    Pair *pb = (Pair*)b;
    if (pa->road_comp != pb->road_comp)
        return pa->road_comp - pb->road_comp;
    return pa->rail_comp - pb->rail_comp;
}

int main() {
    int N, K, L;
    scanf("%d %d %d", &N, &K, &L);

    DSU road_dsu, rail_dsu;
    dsu_init(&road_dsu, N);
    dsu_init(&rail_dsu, N);

    for (int i = 0; i < K; i++) {
        int p, q;
        scanf("%d %d", &p, &q);
        dsu_union(&road_dsu, p, q);
    }
    for (int i = 0; i < L; i++) {
        int r, s;
        scanf("%d %d", &r, &s);
        dsu_union(&rail_dsu, r, s);
    }

    // For each city, get its road component and rail component
    Pair *pairs = (Pair*)malloc((N+1) * sizeof(Pair));
    for (int i = 1; i <= N; i++) {
        pairs[i].road_comp = dsu_find(&road_dsu, i);
        pairs[i].rail_comp = dsu_find(&rail_dsu, i);
    }

    // Sort pairs[1..N] by (road_comp, rail_comp)
    // We'll sort an array of indices or just the pairs themselves
    // Since we need original order for output, we sort copies
    Pair *sorted = (Pair*)malloc((N+1) * sizeof(Pair));
    for (int i = 1; i <= N; i++) {
        sorted[i] = pairs[i];
    }
    qsort(sorted + 1, N, sizeof(Pair), pair_cmp);

    // Count frequencies
    int *freq = (int*)malloc((N+1) * sizeof(int));
    // We'll compute frequencies by scanning sorted array
    int cur_idx = 1;
    while (cur_idx <= N) {
        int start = cur_idx;
        Pair cur = sorted[cur_idx];
        while (cur_idx <= N && sorted[cur_idx].road_comp == cur.road_comp 
                             && sorted[cur_idx].rail_comp == cur.rail_comp) {
            cur_idx++;
        }
        int count = cur_idx - start;
        for (int j = start; j < cur_idx; j++) {
            freq[j] = count;
        }
    }

    // Now we need to map back: for each city i, find its position in sorted array
    // We'll create an array result[N+1]
    int *result = (int*)malloc((N+1) * sizeof(int));
    // Use a simple approach: for each city, binary search in sorted
    // Since N up to 2e5, O(N log N) is fine
    for (int i = 1; i <= N; i++) {
        Pair target = pairs[i];
        // binary search leftmost occurrence
        int lo = 1, hi = N;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (pair_cmp(&sorted[mid], &target) < 0) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        result[i] = freq[lo];
    }

    // Output
    for (int i = 1; i <= N; i++) {
        printf("%d", result[i]);
        if (i < N) printf(" ");
    }
    printf("\n");

    free(pairs);
    free(sorted);
    free(freq);
    free(result);

    return 0;
}

