} DSUNode;

typedef struct {
    int roadRoot;
    int railRoot;
    int city;
} Pair;

void dsu_init(DSUNode *dsu, int n) {
    for (int i = 0; i < n; i++) {
        dsu[i].parent = i;
        dsu[i].size = 1;
    }
}

int dsu_find(DSUNode *dsu, int x) {
    if (dsu[x].parent == x) return x;
    dsu[x].parent = dsu_find(dsu, dsu[x].parent);
    return dsu[x].parent;
}

void dsu_unite(DSUNode *dsu, int a, int b) {
    a = dsu_find(dsu, a);
    b = dsu_find(dsu, b);
    if (a == b) return;
    if (dsu[a].size < dsu[b].size) {
        int t = a; a = b; b = t;
    }
    dsu[b].parent = a;
    dsu[a].size += dsu[b].size;
}

int cmp_pair(const void *a, const void *b) {
    const Pair *x = (const Pair *)a;
    const Pair *y = (const Pair *)b;
    if (x->roadRoot != y->roadRoot) return x->roadRoot - y->roadRoot;
    if (x->railRoot != y->railRoot) return x->railRoot - y->railRoot;
    return x->city - y->city;
}

