            sb.append(count.get(keys[i]));
        }
        sb.append('\n');

        System.out.print(sb.toString());
    }
}

import sys
from collections import defaultdict

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x, y):
        xr, yr = self.find(x), self.find(y)
        if xr == yr:
            return
        if self.rank[xr] < self.rank[yr]:
            self.parent[xr] = yr
        elif self.rank[xr] > self.rank[yr]:
            self.parent[yr] = xr
        else:
            self.parent[yr] = xr
            self.rank[xr] += 1

def solve():
    input_data = sys.stdin.read().split()
    it = iter(input_data)
    N = int(next(it))
    K = int(next(it))
    L = int(next(it))

    dsu_road = DSU(N)
    dsu_rail = DSU(N)

    for _ in range(K):
        p = int(next(it)) - 1
        q = int(next(it)) - 1
        dsu_road.union(p, q)

    for _ in range(L):
        r = int(next(it)) - 1
        s = int(next(it)) - 1
        dsu_rail.union(r, s)

    pair_count = defaultdict(int)
    for i in range(N):
        key = (dsu_road.find(i), dsu_rail.find(i))
        pair_count[key] += 1

    out = []
    for i in range(N):
        key = (dsu_road.find(i), dsu_rail.find(i))
        out.append(str(pair_count[key]))

    sys.stdout.write(" ".join(out))

if __name__ == "__main__":
