import sys


class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x):
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a, b):
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]


def main():
    input = sys.stdin.readline
    N, K, L = map(int, input().split())

    road = DSU(N)
    rail = DSU(N)

    for _ in range(K):
        p, q = map(int, input().split())
        road.union(p - 1, q - 1)

    for _ in range(L):
        r, s = map(int, input().split())
        rail.union(r - 1, s - 1)

    pairs = []
    for i in range(N):
        pairs.append((road.find(i), rail.find(i)))

    count = {}
    for key in pairs:
        count[key] = count.get(key, 0) + 1

    ans = [str(count[key]) for key in pairs]
    print(" ".join(ans))


if __name__ == "__main__":
    main()
